//! The `bsc imprint` command surface. Thin: arg-parsing here, persistence in `bsc-json-store`, and
//! every decision that matters (what is measured, what may be compared) in the crate root where it is
//! tested without a store.
//!
//! THE SURFACE IS READ-MOSTLY BY CONSTRUCTION. `build` writes; `show` and `explain` do not, and
//! `explain` in particular persists NOTHING about the comparison it just made. That is the crate's
//! whole disposition — see the crate docs for why a comparison history is the one thing this must
//! never grow.

use crate::{accumulate, explain, measure, Explain, Kind, Markers, Profile, Source, MIN_WORDS};
use bsc_cli_util::CmdDoc;
use bsc_json_store::Store;
use std::time::{SystemTime, UNIX_EPOCH};

const TAGLINE: &str = "how the user WRITES — a read-only style profile (it decides nothing)";

/// The only profile id anything writes today. The field exists so a second person is a new row
/// rather than a schema change; nothing in this CLI offers to create one.
const ME: &str = "me";

pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "build",
        summary: "fold a corpus into the profile (ACCUMULATES, never replaces)",
        usage: "USAGE:\n  bsc imprint build --file <path> [--label <name>] [--dir <store>]\n  bsc imprint build --transcripts [--label <name>] [--dir <store>]\n\nMeasures the corpus and folds it into the stored profile, weighting each dimension by the number of\nobservations behind it — so a short corpus cannot drag a well-evidenced habit.\n\n--file takes one message per LINE (blank lines skipped). --transcripts reads the user's own turns out\nof the local Claude Code transcripts, which is the corpus this was designed against.\n\nACCUMULATES: the app LEARNS the user rather than enrolling them once, so more corpus only sharpens\nthe profile. Every source folded in is recorded, so `show` can say what the numbers rest on.",
    },
    CmdDoc {
        name: "show",
        summary: "the stored profile: every dimension, its kind, and the corpus it rests on",
        usage: "USAGE:\n  bsc imprint show [--json] [--dir <store>]\n\nPrints the discriminative dimensions, the descriptive ones, the emoticon vocabulary, and the corpus\nbehind them. A profile resting on too little text says so rather than presenting confident numbers.",
    },
    CmdDoc {
        name: "explain",
        summary: "compare text against the profile, PER DIMENSION — no verdict, nothing stored",
        usage: "USAGE:\n  bsc imprint explain \"<text>\" [--json] [--dir <store>]\n  bsc imprint explain --file <path> [--json] [--dir <store>]\n\nReports how the text compares on each DISCRIMINATIVE dimension, and shows the descriptive ones\nalongside without comparing them (averaging them in measurably WORSENED separation).\n\nIT EMITS NO VERDICT and no overall score, and it writes nothing at all — not the text, not the\nresult, not that it was asked. A running record of how often someone failed to look like themselves\nis a suspicion ledger, and this surface does not have one to grow.",
    },
    CmdDoc {
        name: "markers",
        summary: "measure text and print its feature vector, without touching the profile",
        usage: "USAGE:\n  bsc imprint markers \"<text>\" [--json]\n  bsc imprint markers --file <path> [--json]\n\nThe measurement alone — useful for seeing what a dimension actually reads on a given sample.",
    },
];

fn now_ms() -> i64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_millis() as i64).unwrap_or(0)
}
fn flag<'a>(a: &'a [String], n: &str) -> Option<&'a str> {
    a.iter().position(|x| x == n).and_then(|i| a.get(i + 1)).map(String::as_str)
}
fn has(a: &[String], n: &str) -> bool {
    a.iter().any(|x| x == n)
}
const VALUE_FLAGS: &[&str] = &["--dir", "--file", "--label"];

fn positionals(a: &[String]) -> Vec<&str> {
    let mut out = Vec::new();
    let mut skip = false;
    for x in a {
        if skip {
            skip = false;
            continue;
        }
        if VALUE_FLAGS.contains(&x.as_str()) {
            skip = true;
            continue;
        }
        if x.starts_with("--") {
            continue;
        }
        out.push(x.as_str());
    }
    out
}

fn open(a: &[String]) -> Store {
    let dir = flag(a, "--dir")
        .map(std::path::PathBuf::from)
        .or_else(bsc_util::bsc_base_dir)
        .unwrap_or_else(|| std::path::PathBuf::from("."));
    Store::new(dir, "imprint")
}

fn load(store: &Store) -> Option<Profile> {
    store.get(ME).ok().flatten().and_then(|raw| serde_json::from_str(&raw).ok())
}

/// The messages a command was pointed at: `--file` (one per line) or the positional text.
fn corpus(a: &[String]) -> Result<Vec<String>, String> {
    if let Some(p) = flag(a, "--file") {
        let text = std::fs::read_to_string(p).map_err(|e| format!("reading {p}: {e}"))?;
        return Ok(text.lines().map(str::trim).filter(|l| !l.is_empty()).map(str::to_string).collect());
    }
    let text = positionals(a).join(" ");
    if text.trim().is_empty() {
        return Err("no text: pass it as an argument or use --file <path>".into());
    }
    Ok(vec![text])
}

/// The user's own turns from the local Claude Code transcripts — the corpus this was designed
/// against. Best-effort per file: an unreadable or half-written transcript costs its own messages and
/// never the command.
fn transcript_corpus() -> Result<Vec<String>, String> {
    let home = bsc_util::bsc_base_dir()
        .and_then(|d| d.parent().map(std::path::Path::to_path_buf))
        .ok_or("could not resolve a home directory")?;
    let root = home.join(".claude").join("projects");
    let mut out = Vec::new();
    let Ok(projects) = std::fs::read_dir(&root) else {
        return Err(format!("no transcripts at {}", root.display()));
    };
    for p in projects.flatten() {
        let Ok(files) = std::fs::read_dir(p.path()) else { continue };
        for f in files.flatten() {
            if f.path().extension().and_then(|e| e.to_str()) != Some("jsonl") {
                continue;
            }
            let Ok(text) = std::fs::read_to_string(f.path()) else { continue };
            for line in text.lines() {
                let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else { continue };
                if v.get("type").and_then(|t| t.as_str()) != Some("user") {
                    continue;
                }
                let c = v.pointer("/message/content");
                let msg = match c {
                    Some(serde_json::Value::String(s)) => s.clone(),
                    Some(serde_json::Value::Array(parts)) => parts
                        .iter()
                        .filter(|p| p.get("type").and_then(|t| t.as_str()) == Some("text"))
                        .filter_map(|p| p.get("text").and_then(|t| t.as_str()))
                        .collect::<Vec<_>>()
                        .join(" "),
                    _ => continue,
                };
                let t = msg.trim();
                // Skip what the HARNESS injected and what the user PASTED — neither is typing, and
                // counting either measures the tooling rather than the person.
                if t.is_empty() || t.starts_with('<') || t.contains("system-reminder") || t.len() > 1500 {
                    continue;
                }
                out.push(t.to_string());
            }
        }
    }
    if out.is_empty() {
        return Err(format!("no user turns found under {}", root.display()));
    }
    Ok(out)
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &positionals(&args).iter().map(|s| s.to_string()).collect::<Vec<_>>()) {
        return Ok(());
    }
    match args.first().map(String::as_str).unwrap_or("") {
        "build" => build(&args[1..]),
        "show" => show(&args[1..]),
        "explain" => explain_cmd(&args[1..]),
        "markers" => markers_cmd(&args[1..]),
        "" | "help" | "-h" | "--help" => {
            bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &["help".to_string()]);
            Ok(())
        }
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

fn build(args: &[String]) -> Result<(), String> {
    let (msgs, default_label) = if has(args, "--transcripts") {
        (transcript_corpus()?, "transcripts")
    } else {
        (corpus(args)?, "corpus")
    };
    let fresh = measure(&msgs);
    let store = open(args);
    let prior = load(&store);
    let markers = match &prior {
        Some(p) => accumulate(&p.markers, &fresh),
        None => fresh.clone(),
    };
    let mut sources = prior.map(|p| p.sources).unwrap_or_default();
    sources.push(Source {
        label: flag(args, "--label").unwrap_or(default_label).to_string(),
        messages: fresh.messages,
        words: fresh.words,
        at_ms: now_ms(),
    });
    let profile = Profile { id: ME.into(), markers, sources, updated_at_ms: now_ms() };
    store.set(ME, &serde_json::to_string(&profile).map_err(|e| e.to_string())?)?;
    println!(
        "folded {} message(s) / {} word(s); the profile now rests on {} message(s) / {} word(s){}",
        fresh.messages,
        fresh.words,
        profile.markers.messages,
        profile.markers.words,
        if profile.evidenced() { "" } else { " — still under the evidence floor" }
    );
    Ok(())
}

/// A dimension's value, or the word ABSENT. Never a number standing in for "we did not see it".
fn val(v: Option<f64>) -> String {
    v.map(|x| format!("{x:.3}")).unwrap_or_else(|| "ABSENT".into())
}

fn show(args: &[String]) -> Result<(), String> {
    let Some(p) = load(&open(args)) else {
        return Err("no profile yet — build one with `bsc imprint build --transcripts`".into());
    };
    if has(args, "--json") {
        println!("{}", serde_json::to_string(&p).map_err(|e| e.to_string())?);
        return Ok(());
    }
    println!("profile `{}` — {} message(s), {} word(s)", p.id, p.markers.messages, p.markers.words);
    if !p.evidenced() {
        println!(
            "  UNDER-EVIDENCED: {} words against a floor of {MIN_WORDS}. The numbers below are printed \
             because hiding them would be its own lie, but they do not yet mean anything.",
            p.markers.words
        );
    }
    for kind in [Kind::Discriminative, Kind::Descriptive] {
        println!("\n{}:", if kind == Kind::Discriminative { "compared" } else { "reported only (never compared)" });
        for d in p.markers.dims.iter().filter(|d| d.kind == kind) {
            let v = if d.measured() { format!("{:.3}", d.value) } else { "ABSENT".into() };
            println!("  {:22} {:>8}   n={:<7} {}", d.name, v, d.n, d.about);
        }
    }
    if !p.markers.emoticons.is_empty() {
        println!("\nemoticon vocabulary (which faces, not how many — the identifying half):");
        let v: Vec<String> = p.markers.emoticons.iter().map(|(f, n)| format!("{f}·{n}")).collect();
        println!("  {}", v.join("  "));
    }
    println!("\ncorpus folded in:");
    for s in &p.sources {
        println!("  {:14} {:>6} message(s) {:>8} word(s)", s.label, s.messages, s.words);
    }
    Ok(())
}

fn render(e: &Explain) -> String {
    let mut out = String::new();
    if !e.profile_evidenced {
        out.push_str(&format!(
            "THE PROFILE IS UNDER-EVIDENCED ({} words, floor {MIN_WORDS}). Read nothing below as a claim.\n\n",
            e.profile_words
        ));
    }
    out.push_str(&format!("sample: {} word(s)\n\ncompared:\n", e.sample_words));
    for r in &e.readings {
        out.push_str(&format!(
            "  {:22} profile {:>8}   sample {:>8}   delta {:>8}   (n={})\n",
            r.name,
            val(r.profile),
            val(r.sample),
            val(r.delta),
            r.sample_n
        ));
    }
    out.push_str("\nreported only, never compared:\n");
    for r in &e.descriptive {
        out.push_str(&format!("  {:22} profile {:>8}   sample {:>8}\n", r.name, val(r.profile), val(r.sample)));
    }
    if !e.unseen_emoticons.is_empty() {
        out.push_str(&format!(
            "\nemoticons not in the profile: {}\n  (a person using a new face, which people do — not evidence of anything)\n",
            e.unseen_emoticons.join(" ")
        ));
    }
    // Said every time, because a reader who skips it is the reader this warning is for.
    out.push_str(
        "\nNo verdict is offered. A delta is a distance, not a judgement, and a short sample gives \
         ABSENT on most dimensions.\n",
    );
    out
}

fn explain_cmd(args: &[String]) -> Result<(), String> {
    let Some(p) = load(&open(args)) else {
        return Err("no profile yet — build one with `bsc imprint build --transcripts`".into());
    };
    let sample = measure(&corpus(args)?);
    let e = explain(&p, &sample);
    if has(args, "--json") {
        println!("{}", serde_json::to_string(&e).map_err(|e| e.to_string())?);
    } else {
        print!("{}", render(&e));
    }
    // Deliberately no write of any kind. See the crate docs.
    Ok(())
}

fn markers_cmd(args: &[String]) -> Result<(), String> {
    let m: Markers = measure(&corpus(args)?);
    if has(args, "--json") {
        println!("{}", serde_json::to_string(&m).map_err(|e| e.to_string())?);
        return Ok(());
    }
    println!("{} message(s), {} word(s)", m.messages, m.words);
    for d in &m.dims {
        let v = if d.measured() { format!("{:.3}", d.value) } else { "ABSENT".into() };
        println!("  {:22} {:>8}   n={:<7} {:?}", d.name, v, d.n, d.kind);
    }
    if !m.emoticons.is_empty() {
        let v: Vec<String> = m.emoticons.iter().map(|(f, n)| format!("{f}·{n}")).collect();
        println!("  emoticons: {}", v.join("  "));
    }
    Ok(())
}
